const WORLD_ATLAS = "data:image/jpeg;base64,";
const WORLD_PASTORAL = "data:image/jpeg;base64,";
function decorateWorldThumbnail(el,style){
 el.style.display='block';el.style.width='100%';el.style.aspectRatio='1';el.style.backgroundRepeat='no-repeat';
 const pastoral=style.id==='w14';
 el.style.backgroundImage='url("'+(pastoral?WORLD_PASTORAL:WORLD_ATLAS)+'")';
 el.style.backgroundSize=pastoral?'100% 100%':'300% 500%';
 el.style.backgroundPosition=pastoral?'center':(style.previewTile%3*50)+'% '+(Math.floor(style.previewTile/3)*25)+'%';
 el.setAttribute('aria-hidden','true');
}
